import { NextResponse } from "next/server";

/**
 * Public, non-secret customer health/version evidence.
 *
 * Cloudflare deployment verification must be able to prove which customer,
 * environment and approved Main release answered. The values come from
 * `wrangler.jsonc` vars generated by the Main provisioning engine; no secret is
 * returned here.
 */
export const dynamic = "force-dynamic";

function value(...names: string[]): string {
  for (const name of names) {
    const current = process.env[name]?.trim();
    if (current) return current;
  }
  return "unknown";
}

export function GET() {
  const release = value("TRADESSTACK_RELEASE", "DEPLOYMENT_VERSION");
  const environmentId = value("TRADESSTACK_ENVIRONMENT_ID", "TRADESSTACK_ENVIRONMENT");
  const supabaseProjectRef = value("TRADESSTACK_SUPABASE_PROJECT_REF", "TRADESSTACK_ENVIRONMENT_ID");
  const sourceSha = value("TRADESSTACK_SOURCE_SHA", "GIT_SHA");
  const workerName = value("TRADESSTACK_WORKER_NAME");
  const customerKey = value("TRADESSTACK_CUSTOMER_KEY");
  const releaseFingerprint = value("TRADESSTACK_RELEASE_FINGERPRINT");
  const known = release !== "unknown" && supabaseProjectRef !== "unknown";
  const body = {
    ok: known,
    service: "tradesstack",
    customerKey,
    release,
    // The Hub compares the deployed environment to the dedicated Supabase
    // project reference; keep the human environment identity separately.
    environment: supabaseProjectRef,
    environmentId,
    supabaseProjectRef,
    sourceSha,
    releaseFingerprint,
    workerName,
    deploymentId: value("DEPLOYMENT_VERSION", "GIT_SHA"),
    checkedAt: new Date().toISOString(),
  };
  return NextResponse.json(body, {
    status: 200,
    headers: {
      "cache-control": "no-store",
      "x-tradesstack-release": release,
      "x-tradesstack-environment": supabaseProjectRef,
      "x-tradesstack-environment-id": environmentId,
      "x-tradesstack-source-sha": sourceSha,
      "x-tradesstack-worker": workerName,
    },
  });
}
